<?php require 'config.php';
$result=$conn->query('SELECT s.*, COUNT(f.id) file_count FROM students s LEFT JOIN student_files f ON s.id=f.student_id GROUP BY s.id ORDER BY s.id DESC');
?>
<!doctype html><html><head><meta charset="utf-8"><title>Student Admin</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><header><h1>Student Administration</h1><a class="btn" href="form.php">+ Add Student</a></header><table><tr><th>Name</th><th>Roll No.</th><th>Course</th><th>Files</th><th>Actions</th></tr><?php while($row=$result->fetch_assoc()): ?><tr><td><?=htmlspecialchars($row['name'])?></td><td><?=htmlspecialchars($row['roll_number'])?></td><td><?=htmlspecialchars($row['course'])?></td><td><?=$row['file_count']?></td><td><a href="view.php?id=<?=$row['id']?>">View</a> · <a href="form.php?id=<?=$row['id']?>">Edit</a> · <a href="delete.php?id=<?=$row['id']?>" onclick="return confirm('Delete this student?')">Delete</a></td></tr><?php endwhile; ?></table></div></body></html>
